let
    Demo = Binary.Decompress(Binary.FromText("", BinaryEncoding.Base64), Compression.Deflate),
    Source = if DataMode = "Demo" then Demo else if DataMode = "Folder" then File.Contents(DataFolder & "/Orders.csv") else error "DataMode must be Demo or Folder",
    Parsed = Csv.Document(Source, [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    Headers = Table.PromoteHeaders(Parsed, [PromoteAllScalars=true]),
    Typed = Table.TransformColumnTypes(Headers, {{"OrderID", type text}, {"ChannelID", type text}, {"Date", type date}, {"CustomerID", type text}, {"GrossSales", Currency.Type}, {"Discount", Currency.Type}, {"Refund", Currency.Type}, {"NetCOGS", Currency.Type}, {"ShippingCost", Currency.Type}, {"PaymentFee", Currency.Type}, {"FulfilmentCost", Currency.Type}}, "en-US")
in
    Typed
